def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    opp_def = sum(1 for _, o in history if o == 'D')

    if opp_def >= n * 0.8:
        return 'D'

    if n == 99 and opp_def <= 2:
        return 'D'

    last_my, last_opp = history[-1]

    if last_opp == 'C':
        return 'C'

    if history[-2][1] == 'D':
        return 'D'

    return 'C'
